{
  "stages": {
    "prototype": {
      "level": 4,
      "rationale": "For isolated, disposable experiments, speed and learning usually matter more than maintainability. Keep the code away from sensitive data and production systems, and discard or review it before reusing it."
    },
    "proof-of-concept": {
      "level": 3,
      "rationale": "A demo can be built quickly with selective review and checks of the behaviors stakeholders will see. Treat it as a demonstration artifact, and review or replace its code before real users or production depend on it."
    },
    "mvp": {
      "level": 2,
      "rationale": "Real early users can be affected by security, data-loss, and reliability defects, while the code may become the product's foundation. Have a person review every change line by line, with tests and other appropriate checks as well."
    },
    "production": {
      "level": 2,
      "rationale": "Paying customers and ongoing maintenance make defects costly and hard to contain. Review every change line by line and use tests, security checks, and operational monitoring; reserve faster selective review for well-understood, low-impact changes under explicit team policy."
    },
    "critical": {
      "level": 1,
      "rationale": "In regulated or safety-critical systems, AI-generated code should not enter the system as-is. AI may help explain options or suggest approaches, but qualified people should author or rewrite every line and follow the applicable independent verification, documentation, and approval process."
    }
  },
  "summary": "Allow full vibe coding only for disposable, isolated prototypes. As software reaches users and becomes harder to replace, require progressively stronger human review and verification; for critical systems, use AI as an adviser rather than a code author."
}
